from typing import Any, Dict, Optional

from inferencesh import BaseAppInput, BaseAppOutput, OutputMeta
from inferencesh.upstream import Auth, Operation
from pydantic import Field

BASE_URL = "https://api.context.dev/v1"
CREDENTIAL = "context-dev"
AUTH = {
    "bearerAuth": Auth(kind="http", scheme="bearer", secret="CONTEXT_DEV_API_KEY"),
}
DEFAULT_AUTH = "bearerAuth"


# --- news_search: POST /news/search

news_search = Operation(
    name="news_search",
    method="POST",
    path="/news/search",
    body="json",
    annotations={"title": "Search news", "readOnlyHint": False, "destructiveHint": False, "idempotentHint": False, "openWorldHint": True},
    credentials=None,
    summary="Search news",
)


class NewsSearchInput(BaseAppInput, NewsSearchRequest):
    pass


class NewsSearchOutput(BaseAppOutput, NewsSearchResponse):
    raw: Any = Field(default=None, description="The vendor's response, unchanged.")

    @classmethod
    def from_response(cls, data: Any, output_meta: Optional[OutputMeta] = None) -> "NewsSearchOutput":
        body = data if isinstance(data, dict) else {}
        return cls.model_validate({**body, "raw": data, "output_meta": output_meta})
